    disc_title: 'सिर्फ़ अंदाज़े के लिए।',
    disclaimer: 'यह निवेश, टैक्स या लोन की सलाह नहीं है। रिटर्न की गारंटी नहीं है, और बैंक थोड़ा अलग तरीके से राउंड या हिसाब कर सकते हैं। फ़ैसला लेने से पहले अपने बैंक, डाकघर या फ़ंड हाउस से आज की दरें और शर्तें जाँच लें।',
    help_title: 'कैसे इस्तेमाल करें / काम के लिए आइडिया',
    tip1: 'लोन का प्रकार चुनें या अपनी रकम, दर और अवधि लिखें; लिखते ही नतीजे बदलते हैं। शॉर्टकट: 25L = 25 लाख, 1.2Cr = 1.2 करोड़, और ↑ ↓ कुंजी से संख्या बदलें (Shift दबाकर बड़े कदम)।',
    tip2: 'प्रीपेमेंट जोड़ें, जैसे सालाना बोनस से, और देखें कितना ब्याज बचता है। "अवधि घटाएँ" से आमतौर पर "EMI घटाएँ" से ज़्यादा बचत होती है।',
    tip3: 'बैंक, NBFC और दुकान के स्टाफ़: "फ़्लैट रेट बनाम असली रेट" और "नो-कॉस्ट EMI" से ग्राहक को कुछ सेकंड में असली लागत दिखाएँ।',
    tip4: 'होम लोन के टैक्स काग़ज़ों के लिए वित्त वर्ष वाला व्यू इस्तेमाल करें, और CSV डाउनलोड करके शेड्यूल Excel या Google Sheets में खोलें।',
    tip5: '"सारांश कॉपी करें" से WhatsApp या ईमेल के लिए छोटा संदेश बनता है, जिसमें यही हिसाब खोलने वाला लिंक होता है।',
    tip6: 'HR और फ़ाइनेंस टीम: पैसों की समझ वाले सेशन में इसे प्रोजेक्टर पर चलाएँ और SIP, FD, RD और PPF की साथ-साथ तुलना करें।',
    how_title: 'हिसाब कैसे होता है',
    how_emi: 'EMI = P × r × (1+r)^n ÷ ((1+r)^n − 1), जहाँ P लोन है, r सालाना दर ÷ 12 ÷ 100 है और n महीनों की संख्या है (0% पर EMI = P ÷ n)। हर महीने ब्याज = बाकी लोन × r, और EMI का बाकी हिस्सा लोन घटाता है।',
    how_apr: 'APR वह सालाना दर है जिस पर हाथ में आई असली रकम (लोन माइनस फ़ीस) आपकी सारी EMI की वैल्यू के बराबर होती है। यह वही APR है जो लोन देने वाले को की फ़ैक्ट स्टेटमेंट (KFS) में बताना होता है।',
    how_flat: 'फ़्लैट ब्याज = रकम × फ़्लैट रेट × साल। असली दर वह घटते बैलेंस वाली दर है जिससे उतनी ही EMI बनती है।',
    how_sip: 'SIP: आप हर महीने की शुरुआत में निवेश करते हैं और बढ़त हर महीने जुड़ती है (सालाना रिटर्न ÷ 12), जैसे ज़्यादातर फ़ंड कैलकुलेटर में। एकमुश्त निवेश साल में एक बार बढ़ता है। टैक्स और फ़ंड के चार्ज शामिल नहीं हैं।',
    how_fd: 'FD: ब्याज हर तिमाही चक्रवृद्धि से जुड़ता है, जैसा भारतीय बैंक करते हैं। RD: हर मासिक जमा जितने समय रहती है, उतने समय हर तिमाही बढ़ती है। बैंक की राउंडिंग में कुछ रुपयों का फ़र्क़ हो सकता है।',
    how_ppf: 'PPF: साल में ₹1,50,000 तक जमा, ब्याज साल में एक बार जुड़ता है, 15 साल का लॉक-इन, जिसे 5-5 साल के लिए बढ़ा सकते हैं।',
