    help_title: 'কীভাবে ব্যবহার করবেন / কাজের আইডিয়া',
    tip1: 'লোনের ধরন বাছুন বা নিজের পরিমাণ, হার ও মেয়াদ লিখুন; লেখার সঙ্গে সঙ্গে ফল বদলায়। শর্টকাট: 25L = 25 লাখ, 1.2Cr = 1.2 কোটি, আর ↑ ↓ কী দিয়ে সংখ্যা বদলান (বড় ধাপে Shift চেপে)।',
    tip2: 'আগাম পরিশোধ যোগ করুন, যেমন বার্ষিক বোনাস থেকে, আর দেখুন কত সুদ বাঁচে। "মেয়াদ কমান" সাধারণত "EMI কমান"-এর চেয়ে বেশি বাঁচায়।',
    tip3: 'ব্যাংক, NBFC ও দোকানের কর্মীরা: "ফ্ল্যাট রেট বনাম আসল রেট" আর "নো-কস্ট EMI" দিয়ে কয়েক সেকেন্ডে ক্রেতাকে আসল খরচ দেখান।',
