    how_apr: 'APR হলো সেই বার্ষিক হার, যাতে হাতে পাওয়া আসল টাকা (লোন বাদ ফি) আপনার সব EMI-র মূল্যের সমান হয়। ঋণদাতাকে কি ফ্যাক্ট স্টেটমেন্টে (KFS) এই APR-ই জানাতে হয়।',
    how_flat: 'ফ্ল্যাট সুদ = পরিমাণ × ফ্ল্যাট রেট × বছর। আসল হার হলো সেই কমতে থাকা ব্যালেন্সের হার, যাতে একই EMI হয়।',
    how_sip: 'SIP: আপনি প্রতি মাসের শুরুতে বিনিয়োগ করেন আর বৃদ্ধি প্রতি মাসে যোগ হয় (বার্ষিক রিটার্ন ÷ 12), বেশিরভাগ ফান্ড ক্যালকুলেটরের মতো। এককালীন বিনিয়োগ বছরে একবার বাড়ে। কর ও ফান্ডের চার্জ ধরা নেই।',
    how_fd: 'FD: ভারতীয় ব্যাংকের মতো প্রতি ত্রৈমাসিকে চক্রবৃদ্ধি সুদ। RD: প্রতিটি মাসিক জমা যতদিন থাকে, ততদিন প্রতি ত্রৈমাসিকে বাড়ে। ব্যাংকের রাউন্ডিংয়ে কয়েক টাকা তফাত হতে পারে।',
