    ppf_note: 'દર મહિને 5 તારીખથી મહિનાના અંત સુધીના સૌથી ઓછા બૅલેન્સ પર વ્યાજ ગણાય છે અને વર્ષમાં એક વાર 31 માર્ચે ઉમેરાય છે. એ મહિનાનું વ્યાજ મેળવવા 5 તારીખ સુધીમાં જમા કરો.',
    disc_title: 'ફક્ત અંદાજ માટે.',
    disclaimer: 'આ રોકાણ, ટૅક્સ કે લોનની સલાહ નથી. વળતરની ગૅરંટી નથી, અને બૅંકો થોડી અલગ રીતે રાઉન્ડ કે ગણતરી કરી શકે. નિર્ણય લેતાં પહેલાં તમારી બૅંક, પોસ્ટ ઑફિસ કે ફંડ હાઉસમાં આજના દર અને શરતો તપાસો.',
    help_title: 'કેવી રીતે વાપરવું / કામ માટે આઇડિયા',
    tip1: 'લોનનો પ્રકાર પસંદ કરો કે તમારી રકમ, દર અને મુદત લખો; લખતાં જ પરિણામ બદલાય છે. શૉર્ટકટ: 25L = 25 લાખ, 1.2Cr = 1.2 કરોડ, અને ↑ ↓ કીથી સંખ્યા બદલો (મોટા પગલા માટે Shift દબાવો).',
    tip2: 'પ્રીપેમેન્ટ ઉમેરો, દા.ત. વાર્ષિક બોનસમાંથી, અને જુઓ કેટલું વ્યાજ બચે છે. "મુદત ઘટાડો" સામાન્ય રીતે "EMI ઘટાડો" કરતાં વધુ બચાવે છે.',
    tip3: 'બૅંક, NBFC અને દુકાનના સ્ટાફ: "ફ્લૅટ રેટ સામે સાચો રેટ" અને "નો-કૉસ્ટ EMI" વડે ગ્રાહકને થોડી સેકન્ડમાં સાચો ખર્ચ બતાવો.',
    tip4: 'હોમ લોનના ટૅક્સ કાગળો માટે નાણાકીય વર્ષનો વ્યૂ વાપરો, અને CSV ડાઉનલોડ કરીને શેડ્યૂલ Excel કે Google Sheetsમાં ખોલો.',
    tip5: '"સારાંશ કૉપિ કરો" WhatsApp કે ઈમેલ માટે ટૂંકો સંદેશ બનાવે છે, જેમાં આ જ ગણતરી ખોલતી લિંક હોય છે.',
    tip6: 'HR અને ફાઇનાન્સ ટીમ: પૈસાની સમજના સેશનમાં તેને પ્રોજેક્ટર પર ચલાવો અને SIP, FD, RD અને PPFની સાથે-સાથે સરખામણી કરો.',
    how_title: 'ગણતરી કેવી રીતે થાય છે',
    how_emi: 'EMI = P × r × (1+r)^n ÷ ((1+r)^n − 1), જ્યાં P લોન, r વાર્ષિક દર ÷ 12 ÷ 100 અને n મહિનાની સંખ્યા છે (0% પર EMI = P ÷ n). દર મહિને વ્યાજ = બાકી લોન × r, અને EMIનો બાકીનો ભાગ લોન ઘટાડે છે.',
    how_apr: 'APR એ એવો વાર્ષિક દર છે જેના પર હાથમાં આવેલી સાચી રકમ (લોન બાદ ફી) તમારા બધા EMIના મૂલ્ય જેટલી થાય. ધિરાણકર્તાએ કી ફૅક્ટ સ્ટેટમેન્ટ (KFS)માં આ જ APR જણાવવો પડે છે.',
    how_flat: 'ફ્લૅટ વ્યાજ = રકમ × ફ્લૅટ રેટ × વર્ષ. સાચો દર એ ઘટતા બૅલેન્સનો દર છે જેનાથી એટલો જ EMI આવે.',
    how_sip: 'SIP: તમે દર મહિનાની શરૂઆતમાં રોકાણ કરો છો અને વધારો દર મહિને ઉમેરાય છે (વાર્ષિક વળતર ÷ 12), મોટા ભાગના ફંડ કૅલ્ક્યુલેટરની જેમ. એકસામટું રોકાણ વર્ષે એક વાર વધે છે. ટૅક્સ અને ફંડના ચાર્જ ગણ્યા નથી.',
    how_fd: 'FD: ભારતીય બૅંકોની જેમ દર ત્રિમાસિકે ચક્રવૃદ્ધિ વ્યાજ. RD: દરેક માસિક જમા જેટલો સમય રહે તેટલો સમય દર ત્રિમાસિકે વધે છે. બૅંકના રાઉન્ડિંગમાં થોડા રૂપિયાનો ફરક આવી શકે.',
