    tip1: 'ਲੋਨ ਦੀ ਕਿਸਮ ਚੁਣੋ ਜਾਂ ਆਪਣੀ ਰਕਮ, ਦਰ ਅਤੇ ਮਿਆਦ ਲਿਖੋ; ਲਿਖਦੇ ਹੀ ਨਤੀਜੇ ਬਦਲਦੇ ਹਨ। ਸ਼ਾਰਟਕੱਟ: 25L = 25 ਲੱਖ, 1.2Cr = 1.2 ਕਰੋੜ, ਅਤੇ ↑ ↓ ਕੁੰਜੀਆਂ ਨਾਲ ਗਿਣਤੀ ਬਦਲੋ (ਵੱਡੇ ਕਦਮ ਲਈ Shift ਦਬਾਓ)।',
