    fd_note: 'ବ୍ୟାଙ୍କ FD ଓ RDରେ ପ୍ରତି ତ୍ରୈମାସିକ ସୁଧ ଯୋଡ଼େ; 6 ମାସରୁ କମ୍ ପାଇଁ ସରଳ ସୁଧ ଦିଏ। ମାସିକ ସୁଧ ହାର ÷ 12ଠାରୁ ଟିକେ କମ୍, କାରଣ ବ୍ୟାଙ୍କ ତାହାକୁ ରିହାତି କରି ହିସାବ କରେ। ବାର୍ଷିକ ସୁଧ ସୀମା ଟପିଲେ TDS କଟିପାରେ; ଯୋଗ୍ୟ ହେଲେ ଫର୍ମ 15G/15H ଦିଅନ୍ତୁ।',
    ppf_title: 'PPF (ପବ୍ଲିକ ପ୍ରୋଭିଡେଣ୍ଟ ଫଣ୍ଡ)',
