    ppf_over: 'PPFରେ ବର୍ଷକୁ ସର୍ବାଧିକ ₹1,50,000 ଜମା ହୁଏ, ତେଣୁ କେବଳ ₹1,50,000 ଧରାଯାଇଛି।',
    ppf_under: 'ଖାତା ଚାଲୁ ରଖିବାକୁ PPFରେ ବର୍ଷକୁ ଅତି କମ୍‌ରେ ₹500 ଜମା କରିବାକୁ ପଡ଼େ।',
