    ppf_ext: '15 ବର୍ଷ ପରେ ଅବଧି ବଢ଼ାନ୍ତୁ',
    ppf_ext_none: 'ନା (15 ବର୍ଷ)',
    ppf_ext_n: '+{n} ବର୍ଷ (ମୋଟ {y} ବର୍ଷ)',
    ppf_ext_dep: 'ବଢ଼ାଯାଇଥିବା ଅବଧିରେ ବି ଜମା ଜାରି ରଖନ୍ତୁ',
    ppf_rate_hint: 'PPF ହାର ସରକାର ପ୍ରତି ତ୍ରୈମାସିକ ସ୍ଥିର କରନ୍ତି। ଆଜିର ହାର ଯାଞ୍ଚ କରନ୍ତୁ।',
    ppf_sub: '{y} ବର୍ଷ ପରେ, ବାର୍ଷିକ {r} ହାରରେ',
    ppf_years: 'ସମୟ',
    ppf_tax: 'ଟିକସମୁକ୍ତ: PPFର ସୁଧ ଓ ମ୍ୟାଚ୍ୟୁରିଟି ରାଶିରେ ଟିକସ ନାହିଁ, ଏବଂ ପୁରୁଣା ଟିକସ ବ୍ୟବସ୍ଥାରେ ଜମାରେ ସେକ୍ସନ 80Cର ସୁବିଧା ମିଳେ।',
    sum_ppf: 'ବର୍ଷକୁ {amt} PPF, {r} ହାରରେ {y} ବର୍ଷ: ସୁଧ {int}, ମ୍ୟାଚ୍ୟୁରିଟି ରାଶି {mat}।',
    ppf_note: 'ପ୍ରତି ମାସ 5 ତାରିଖରୁ ମାସ ଶେଷ ପର୍ଯ୍ୟନ୍ତ ସବୁଠୁ କମ୍ ବାକି ଉପରେ ସୁଧ ହିସାବ ହୁଏ ଏବଂ ବର୍ଷକୁ ଥରେ 31 ମାର୍ଚ୍ଚରେ ଯୋଗ ହୁଏ। ସେହି ମାସର ସୁଧ ପାଇବାକୁ 5 ତାରିଖ ସୁଦ୍ଧା ଜମା କରନ୍ତୁ।',
    disc_title: 'କେବଳ ଆନୁମାନିକ।',
    disclaimer: 'ଏହା ନିବେଶ, ଟିକସ ବା ଋଣ ପରାମର୍ଶ ନୁହେଁ। ରିଟର୍ନର ଗ୍ୟାରେଣ୍ଟି ନାହିଁ, ଏବଂ ବ୍ୟାଙ୍କ ଟିକେ ଅଲଗା ଭାବେ ରାଉଣ୍ଡ ବା ହିସାବ କରିପାରେ। ନିଷ୍ପତ୍ତି ନେବା ପୂର୍ବରୁ ଆପଣଙ୍କ ବ୍ୟାଙ୍କ, ଡାକଘର ବା ଫଣ୍ଡ ହାଉସରୁ ଆଜିର ହାର ଓ ସର୍ତ୍ତ ଯାଞ୍ଚ କରନ୍ତୁ।',
    help_title: 'କିପରି ବ୍ୟବହାର କରିବେ / କାମ ପାଇଁ ଚିନ୍ତାଧାରା',
    tip1: 'ଋଣର ପ୍ରକାର ବାଛନ୍ତୁ ବା ନିଜ ରାଶି, ହାର ଓ ଅବଧି ଲେଖନ୍ତୁ; ଲେଖିବା ସାଙ୍ଗେ ସାଙ୍ଗେ ଫଳ ବଦଳେ। ସର୍ଟକଟ୍: 25L = 25 ଲକ୍ଷ, 1.2Cr = 1.2 କୋଟି, ଏବଂ ↑ ↓ ଚାବିରେ ସଂଖ୍ୟା ବଦଳାନ୍ତୁ (ବଡ଼ ପାଦ ପାଇଁ Shift ଦବାନ୍ତୁ)।',
    tip2: 'ଆଗୁଆ ପରିଶୋଧ ଯୋଡ଼ନ୍ତୁ, ଯେପରି ବାର୍ଷିକ ବୋନସରୁ, ଏବଂ ଦେଖନ୍ତୁ କେତେ ସୁଧ ବଞ୍ଚେ। "ଅବଧି କମାନ୍ତୁ" ସାଧାରଣତଃ "EMI କମାନ୍ତୁ"ଠାରୁ ଅଧିକ ବଞ୍ଚାଏ।',
    tip3: 'ବ୍ୟାଙ୍କ, NBFC ଓ ଦୋକାନ କର୍ମଚାରୀ: "ଫ୍ଲାଟ ରେଟ୍ ବନାମ ପ୍ରକୃତ ରେଟ୍" ଓ "ନୋ-କଷ୍ଟ EMI" ଦ୍ୱାରା ଗ୍ରାହକଙ୍କୁ କିଛି ସେକେଣ୍ଡରେ ପ୍ରକୃତ ଖର୍ଚ୍ଚ ଦେଖାନ୍ତୁ।',
    tip4: 'ଗୃହ ଋଣର ଟିକସ କାଗଜ ପାଇଁ ଆର୍ଥିକ ବର୍ଷ ଭ୍ୟୁ ବ୍ୟବହାର କରନ୍ତୁ, ଏବଂ CSV ଡାଉନଲୋଡ୍ କରି ତାଲିକାକୁ Excel ବା Google Sheetsରେ ଖୋଲନ୍ତୁ।',
    tip5: '"ସାରାଂଶ କପି କରନ୍ତୁ" WhatsApp ବା ଇମେଲ ପାଇଁ ଛୋଟ ବାର୍ତ୍ତା ତିଆରି କରେ, ସେଥିରେ ଏହି ହିସାବ ଖୋଲିବା ଲିଙ୍କ ଥାଏ।',
    tip6: 'HR ଓ ଫାଇନାନ୍ସ ଦଳ: ଟଙ୍କା ବୁଝିବା ସେସନରେ ଏହାକୁ ପ୍ରୋଜେକ୍ଟରରେ ଚଲାନ୍ତୁ ଏବଂ SIP, FD, RD ଓ PPF ପାଖାପାଖି ତୁଳନା କରନ୍ତୁ।',
    how_title: 'ହିସାବ କିପରି ହୁଏ',
    how_emi: 'EMI = P × r × (1+r)^n ÷ ((1+r)^n − 1), ଯେଉଁଠି P ଋଣ, r ବାର୍ଷିକ ହାର ÷ 12 ÷ 100 ଏବଂ n ମାସ ସଂଖ୍ୟା (0%ରେ EMI = P ÷ n)। ପ୍ରତି ମାସ ସୁଧ = ବାକି ଋଣ × r, ଏବଂ EMIର ବାକି ଅଂଶ ଋଣ କମାଏ।',
    how_apr: 'APR ହେଉଛି ସେହି ବାର୍ଷିକ ହାର, ଯେଉଁଥିରେ ହାତକୁ ଆସିଥିବା ପ୍ରକୃତ ଟଙ୍କା (ଋଣ ବିଯୁକ୍ତ ଫି) ଆପଣଙ୍କ ସବୁ EMIର ମୂଲ୍ୟ ସହ ସମାନ ହୁଏ। ଋଣଦାତାଙ୍କୁ କି ଫ୍ୟାକ୍ଟ ଷ୍ଟେଟମେଣ୍ଟ (KFS)ରେ ଏହି APR ଜଣାଇବାକୁ ପଡ଼େ।',
    how_flat: 'ଫ୍ଲାଟ ସୁଧ = ରାଶି × ଫ୍ଲାଟ ରେଟ୍ × ବର୍ଷ। ପ୍ରକୃତ ହାର ହେଉଛି ସେହି କମୁଥିବା ବାକିର ହାର, ଯେଉଁଥିରେ ସମାନ EMI ହୁଏ।',
    how_sip: 'SIP: ଆପଣ ପ୍ରତି ମାସ ଆରମ୍ଭରେ ନିବେଶ କରନ୍ତି ଏବଂ ବୃଦ୍ଧି ପ୍ରତି ମାସ ଯୋଗ ହୁଏ (ବାର୍ଷିକ ରିଟର୍ନ ÷ 12), ଅଧିକାଂଶ ଫଣ୍ଡ କ୍ୟାଲକୁଲେଟର ପରି। ଏକକାଳୀନ ନିବେଶ ବର୍ଷକୁ ଥରେ ବଢ଼େ। ଟିକସ ଓ ଫଣ୍ଡ ଚାର୍ଜ ଧରାଯାଇନାହିଁ।',
    how_fd: 'FD: ଭାରତୀୟ ବ୍ୟାଙ୍କ ପରି ପ୍ରତି ତ୍ରୈମାସିକ ଚକ୍ରବୃଦ୍ଧି ସୁଧ। RD: ପ୍ରତିଟି ମାସିକ ଜମା ଯେତେ ସମୟ ରହେ, ସେତେ ସମୟ ପ୍ରତି ତ୍ରୈମାସିକ ବଢ଼େ। ବ୍ୟାଙ୍କର ରାଉଣ୍ଡିଂରେ କିଛି ଟଙ୍କାର ଫରକ ହୋଇପାରେ।',
    how_ppf: 'PPF: ବର୍ଷକୁ ₹1,50,000 ପର୍ଯ୍ୟନ୍ତ ଜମା, ସୁଧ ବର୍ଷକୁ ଥରେ ଯୋଗ ହୁଏ, 15 ବର୍ଷର ଲକ୍-ଇନ୍, ଯାହା 5 ବର୍ଷ ଲେଖାଏଁ ବଢ଼ାଇହେବ।',
