    af_help: 'எல்லா EMI-களும் சேர்ந்து கைக்கு வரும் சம்பளத்தில் சுமார் 40–50%-க்குள் இருக்க வேண்டும் என்று கடன் தருபவர்கள் விரும்புவார்கள். மேலே உள்ள EMI பயன்படும்.',
    af_income: 'மாதம் கைக்கு வரும் சம்பளம்',
    af_other: 'மாதம் பிற EMI-கள்',
