    af_all: 'எல்லா EMI-களும்',
    af_share: 'சம்பளத்தில் பங்கு',
    af_left: 'EMI-க்குப் பின் மாதம் மீதி',
    af_max: 'உங்கள் வரம்புக்குள் மிகப் பெரிய கடன்',
    af_ok: 'நிம்மதி: உங்கள் வரம்புக்குள் நன்றாகவே இருக்கிறது.',
    af_tight: 'வரம்புக்குள், ஆனால் இறுக்கம். சுமார் 6 மாதச் செலவுக்கான அவசர நிதி வைத்திருங்கள்.',
    af_over: 'உங்கள் வரம்பைத் தாண்டுகிறது. கடன் தருபவர் தொகையைக் குறைக்கலாம் அல்லது மறுக்கலாம்; நீண்ட காலம் அல்லது சிறிய கடனை முயலுங்கள்.',
    sip_title: 'SIP (மியூச்சுவல் ஃபண்ட்) கால்குலேட்டர்',
