    fd_note: 'బ్యాంకులు FD, RD వడ్డీని ప్రతి త్రైమాసికం కలుపుతాయి; 6 నెలల లోపు అయితే సాధారణ వడ్డీ ఇస్తాయి. నెలవారీ వడ్డీ రేటు ÷ 12 కంటే కొంచెం తక్కువ, ఎందుకంటే బ్యాంకులు దాన్ని డిస్కౌంట్ చేస్తాయి. ఏడాది వడ్డీ పరిమితి దాటితే TDS కట్ కావచ్చు; అర్హత ఉంటే ఫారం 15G/15H ఇవ్వండి.',
