    ppf_sub: '{y} సంవత్సరాల తర్వాత, ఏడాదికి {r} రేటుతో',
    ppf_years: 'కాలం',
    ppf_tax: 'పన్ను రహితం: PPF వడ్డీ, మెచ్యూరిటీ మొత్తంపై పన్ను లేదు; పాత పన్ను విధానంలో జమలకు సెక్షన్ 80C ప్రయోజనం ఉంటుంది.',
    sum_ppf: 'ఏడాదికి {amt} PPF, {r} రేటుతో {y} సంవత్సరాలు: వడ్డీ {int}, మెచ్యూరిటీ మొత్తం {mat}.',
    ppf_note: 'ప్రతి నెల 5వ తేదీ నుంచి నెలాఖరు వరకు ఉన్న కనిష్ఠ బ్యాలెన్స్‌పై వడ్డీ లెక్కించి, ఏడాదికి ఒకసారి మార్చి 31న కలుపుతారు. ఆ నెల వడ్డీ పొందడానికి 5వ తేదీ లోపు జమ చేయండి.',
    disc_title: 'అంచనా కోసం మాత్రమే.',
    disclaimer: 'ఇది పెట్టుబడి, పన్ను లేదా లోన్ సలహా కాదు. రాబడికి హామీ లేదు, బ్యాంకులు కొంచెం వేరుగా రౌండ్ చేయొచ్చు లేదా లెక్కించొచ్చు. నిర్ణయం తీసుకునే ముందు మీ బ్యాంక్, పోస్టాఫీసు లేదా ఫండ్ హౌస్‌లో ఈరోజు రేట్లు, షరతులు చూసుకోండి.',
    help_title: 'ఎలా వాడాలి / పనికి ఆలోచనలు',
    tip1: 'లోన్ రకం ఎంచుకోండి లేదా మీ మొత్తం, రేటు, కాలం రాయండి; రాస్తుండగానే ఫలితాలు మారుతాయి. షార్ట్‌కట్: 25L = 25 లక్షలు, 1.2Cr = 1.2 కోట్లు, ↑ ↓ కీలతో సంఖ్య మార్చండి (పెద్ద అడుగుకు Shift).',
    tip2: 'ముందస్తు చెల్లింపు జోడించండి, ఉదా. ఏడాది బోనస్ నుంచి, ఎంత వడ్డీ ఆదా అవుతుందో చూడండి. "కాలం తగ్గించండి" సాధారణంగా "EMI తగ్గించండి" కంటే ఎక్కువ ఆదా చేస్తుంది.',
    tip3: 'బ్యాంక్, NBFC, దుకాణ సిబ్బంది: "ఫ్లాట్ రేటు vs అసలు రేటు", "నో-కాస్ట్ EMI" ద్వారా కస్టమర్‌కు కొన్ని సెకన్లలో అసలు ఖర్చు చూపించండి.',
    tip4: 'హోమ్ లోన్ పన్ను పత్రాలకు ఆర్థిక సంవత్సరం వీక్షణ వాడండి; CSV డౌన్‌లోడ్ చేసి పట్టికను Excel లేదా Google Sheetsలో తెరవండి.',
    tip5: '"సారాంశం కాపీ చేయండి" WhatsApp లేదా ఈమెయిల్ కోసం చిన్న సందేశం తయారు చేస్తుంది, ఇదే లెక్క తెరిచే లింక్‌తో.',
    tip6: 'HR, ఫైనాన్స్ బృందాలు: డబ్బు అవగాహన సెషన్‌లో దీన్ని ప్రొజెక్టర్‌పై చూపించి SIP, FD, RD, PPFలను పక్కపక్కనే పోల్చండి.',
    how_title: 'లెక్క ఎలా',
    how_emi: 'EMI = P × r × (1+r)^n ÷ ((1+r)^n − 1); ఇక్కడ P లోన్, r వార్షిక రేటు ÷ 12 ÷ 100, n నెలల సంఖ్య (0% అయితే EMI = P ÷ n). ప్రతి నెల వడ్డీ = మిగిలిన లోన్ × r; EMIలో మిగతాది లోన్ తగ్గిస్తుంది.',
    how_apr: 'APR అంటే చేతికి వచ్చిన అసలు డబ్బు (లోన్ మైనస్ ఫీజులు) మీ అన్ని EMIల విలువకు సమానమయ్యే వార్షిక రేటు. రుణదాత కీ ఫ్యాక్ట్ స్టేట్‌మెంట్ (KFS)లో ఇదే APR చూపించాలి.',
    how_flat: 'ఫ్లాట్ వడ్డీ = మొత్తం × ఫ్లాట్ రేటు × సంవత్సరాలు. అసలు రేటు అంటే అదే EMI ఇచ్చే తగ్గే బ్యాలెన్స్ రేటు.',
    how_sip: 'SIP: ప్రతి నెల ప్రారంభంలో పెట్టుబడి పెడతారు, పెరుగుదల ప్రతి నెల కలుస్తుంది (వార్షిక రాబడి ÷ 12), చాలా ఫండ్ కాలిక్యులేటర్ల లాగానే. ఒకేసారి పెట్టుబడి ఏడాదికి ఒకసారి పెరుగుతుంది. పన్నులు, ఫండ్ ఛార్జీలు లెక్కలో లేవు.',
    how_fd: 'FD: భారతీయ బ్యాంకుల లాగా ప్రతి త్రైమాసికం చక్రవడ్డీ. RD: ప్రతి నెలవారీ జమ ఉన్నంత కాలం ప్రతి త్రైమాసికం పెరుగుతుంది. బ్యాంకుల రౌండింగ్‌లో కొన్ని రూపాయల తేడా ఉండొచ్చు.',
    how_ppf: 'PPF: ఏడాదికి ₹1,50,000 వరకు జమ, వడ్డీ ఏడాదికి ఒకసారి కలుస్తుంది, 15 ఏళ్ల లాక్-ఇన్, దాన్ని 5 ఏళ్ల చొప్పున పొడిగించవచ్చు.',
