    ppf_note: 'ಪ್ರತಿ ತಿಂಗಳ 5ನೇ ತಾರೀಖಿನಿಂದ ತಿಂಗಳ ಕೊನೆಯವರೆಗಿನ ಕನಿಷ್ಠ ಬಾಕಿಯ ಮೇಲೆ ಬಡ್ಡಿ ಲೆಕ್ಕವಾಗಿ, ವರ್ಷಕ್ಕೊಮ್ಮೆ ಮಾರ್ಚ್ 31ರಂದು ಸೇರುತ್ತದೆ. ಆ ತಿಂಗಳ ಬಡ್ಡಿ ಪಡೆಯಲು 5ನೇ ತಾರೀಖಿನೊಳಗೆ ಜಮಾ ಮಾಡಿ.',
    disc_title: 'ಅಂದಾಜಿಗೆ ಮಾತ್ರ.',
    disclaimer: 'ಇದು ಹೂಡಿಕೆ, ತೆರಿಗೆ ಅಥವಾ ಸಾಲದ ಸಲಹೆ ಅಲ್ಲ. ಆದಾಯಕ್ಕೆ ಖಾತರಿ ಇಲ್ಲ, ಬ್ಯಾಂಕುಗಳು ಸ್ವಲ್ಪ ಬೇರೆ ರೀತಿಯಲ್ಲಿ ಪೂರ್ಣಾಂಕ ಅಥವಾ ಲೆಕ್ಕ ಮಾಡಬಹುದು. ನಿರ್ಧರಿಸುವ ಮೊದಲು ನಿಮ್ಮ ಬ್ಯಾಂಕ್, ಅಂಚೆ ಕಚೇರಿ ಅಥವಾ ಫಂಡ್ ಹೌಸ್‌ನಲ್ಲಿ ಇಂದಿನ ದರ ಮತ್ತು ಷರತ್ತು ಪರಿಶೀಲಿಸಿ.',
    help_title: 'ಬಳಸುವುದು ಹೇಗೆ / ಕೆಲಸಕ್ಕೆ ಆಲೋಚನೆಗಳು',
    tip1: 'ಸಾಲದ ಪ್ರಕಾರ ಆರಿಸಿ ಅಥವಾ ನಿಮ್ಮ ಮೊತ್ತ, ದರ, ಅವಧಿ ಬರೆಯಿರಿ; ಬರೆಯುತ್ತಿದ್ದಂತೆ ಫಲಿತಾಂಶ ಬದಲಾಗುತ್ತದೆ. ಶಾರ್ಟ್‌ಕಟ್: 25L = 25 ಲಕ್ಷ, 1.2Cr = 1.2 ಕೋಟಿ, ↑ ↓ ಕೀಗಳಿಂದ ಸಂಖ್ಯೆ ಬದಲಿಸಿ (ದೊಡ್ಡ ಹೆಜ್ಜೆಗೆ Shift).',
    tip2: 'ಮುಂಗಡ ಪಾವತಿ ಸೇರಿಸಿ, ಉದಾ. ವಾರ್ಷಿಕ ಬೋನಸ್‌ನಿಂದ, ಎಷ್ಟು ಬಡ್ಡಿ ಉಳಿಯುತ್ತದೆ ನೋಡಿ. "ಅವಧಿ ಕಡಿಮೆ ಮಾಡಿ" ಸಾಮಾನ್ಯವಾಗಿ "EMI ಕಡಿಮೆ ಮಾಡಿ"ಗಿಂತ ಹೆಚ್ಚು ಉಳಿಸುತ್ತದೆ.',
    tip3: 'ಬ್ಯಾಂಕ್, NBFC ಮತ್ತು ಅಂಗಡಿ ಸಿಬ್ಬಂದಿ: "ಫ್ಲ್ಯಾಟ್ ದರ vs ನಿಜವಾದ ದರ" ಮತ್ತು "ನೋ-ಕಾಸ್ಟ್ EMI" ಬಳಸಿ ಗ್ರಾಹಕರಿಗೆ ಕೆಲವೇ ಸೆಕೆಂಡುಗಳಲ್ಲಿ ನಿಜವಾದ ವೆಚ್ಚ ತೋರಿಸಿ.',
    tip4: 'ಗೃಹ ಸಾಲದ ತೆರಿಗೆ ದಾಖಲೆಗಳಿಗೆ ಹಣಕಾಸು ವರ್ಷದ ನೋಟ ಬಳಸಿ; CSV ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ ಪಟ್ಟಿಯನ್ನು Excel ಅಥವಾ Google Sheetsನಲ್ಲಿ ತೆರೆಯಿರಿ.',
    tip5: '"ಸಾರಾಂಶ ನಕಲಿಸಿ" WhatsApp ಅಥವಾ ಇಮೇಲ್‌ಗೆ ಚಿಕ್ಕ ಸಂದೇಶ ರಚಿಸುತ್ತದೆ, ಇದೇ ಲೆಕ್ಕ ತೆರೆಯುವ ಲಿಂಕ್ ಸಹಿತ.',
    tip6: 'HR ಮತ್ತು ಹಣಕಾಸು ತಂಡಗಳು: ಹಣದ ಅರಿವಿನ ಸೆಷನ್‌ನಲ್ಲಿ ಇದನ್ನು ಪ್ರೊಜೆಕ್ಟರ್‌ನಲ್ಲಿ ತೋರಿಸಿ SIP, FD, RD ಮತ್ತು PPF ಅಕ್ಕಪಕ್ಕ ಹೋಲಿಸಿ.',
    how_title: 'ಲೆಕ್ಕ ಹೇಗೆ',
    how_emi: 'EMI = P × r × (1+r)^n ÷ ((1+r)^n − 1); ಇಲ್ಲಿ P ಸಾಲ, r ವಾರ್ಷಿಕ ದರ ÷ 12 ÷ 100, n ತಿಂಗಳ ಸಂಖ್ಯೆ (0%ಗೆ EMI = P ÷ n). ಪ್ರತಿ ತಿಂಗಳು ಬಡ್ಡಿ = ಬಾಕಿ ಸಾಲ × r; EMIಯ ಉಳಿದ ಭಾಗ ಸಾಲ ಇಳಿಸುತ್ತದೆ.',
    how_apr: 'APR ಎಂದರೆ ಕೈಗೆ ಬಂದ ನಿಜವಾದ ಹಣ (ಸಾಲ ಮೈನಸ್ ಶುಲ್ಕ) ನಿಮ್ಮ ಎಲ್ಲ EMIಗಳ ಮೌಲ್ಯಕ್ಕೆ ಸಮವಾಗುವ ವಾರ್ಷಿಕ ದರ. ಸಾಲದಾತರು ಕೀ ಫ್ಯಾಕ್ಟ್ ಸ್ಟೇಟ್‌ಮೆಂಟ್ (KFS)ನಲ್ಲಿ ಇದೇ APR ತೋರಿಸಬೇಕು.',
    how_flat: 'ಫ್ಲ್ಯಾಟ್ ಬಡ್ಡಿ = ಮೊತ್ತ × ಫ್ಲ್ಯಾಟ್ ದರ × ವರ್ಷ. ನಿಜವಾದ ದರ ಎಂದರೆ ಅದೇ EMI ಕೊಡುವ ಇಳಿಯುವ ಬಾಕಿಯ ದರ.',
    how_sip: 'SIP: ಪ್ರತಿ ತಿಂಗಳ ಆರಂಭದಲ್ಲಿ ಹೂಡಿಕೆ ಮಾಡುತ್ತೀರಿ, ಬೆಳವಣಿಗೆ ಪ್ರತಿ ತಿಂಗಳು ಸೇರುತ್ತದೆ (ವಾರ್ಷಿಕ ಆದಾಯ ÷ 12), ಹೆಚ್ಚಿನ ಫಂಡ್ ಕ್ಯಾಲ್ಕುಲೇಟರ್‌ಗಳಂತೆ. ಒಮ್ಮೆಲೇ ಹೂಡಿಕೆ ವರ್ಷಕ್ಕೊಮ್ಮೆ ಬೆಳೆಯುತ್ತದೆ. ತೆರಿಗೆ ಮತ್ತು ಫಂಡ್ ಶುಲ್ಕ ಸೇರಿಲ್ಲ.',
    how_fd: 'FD: ಭಾರತೀಯ ಬ್ಯಾಂಕುಗಳಂತೆ ಪ್ರತಿ ತ್ರೈಮಾಸಿಕ ಚಕ್ರಬಡ್ಡಿ. RD: ಪ್ರತಿ ಮಾಸಿಕ ಜಮೆ ಇರುವಷ್ಟು ಕಾಲ ಪ್ರತಿ ತ್ರೈಮಾಸಿಕ ಬೆಳೆಯುತ್ತದೆ. ಬ್ಯಾಂಕುಗಳ ಪೂರ್ಣಾಂಕದಲ್ಲಿ ಕೆಲವು ರೂಪಾಯಿ ವ್ಯತ್ಯಾಸ ಇರಬಹುದು.',
