    disc_title: 'ഏകദേശ കണക്ക് മാത്രം.',
    disclaimer: 'ഇത് നിക്ഷേപ, നികുതി, വായ്പ ഉപദേശമല്ല. ആദായത്തിന് ഉറപ്പില്ല, ബാങ്കുകൾ അല്പം വ്യത്യസ്തമായി റൗണ്ട് ചെയ്യുകയോ കണക്കാക്കുകയോ ചെയ്യാം. തീരുമാനിക്കും മുമ്പ് നിങ്ങളുടെ ബാങ്കിലോ പോസ്റ്റ് ഓഫീസിലോ ഫണ്ട് ഹൗസിലോ ഇന്നത്തെ നിരക്കുകളും വ്യവസ്ഥകളും പരിശോധിക്കൂ.',
    help_title: 'എങ്ങനെ ഉപയോഗിക്കാം / ജോലിക്കുള്ള ആശയങ്ങൾ',
    tip1: 'വായ്പയുടെ തരം തിരഞ്ഞെടുക്കൂ, അല്ലെങ്കിൽ നിങ്ങളുടെ തുക, നിരക്ക്, കാലാവധി എഴുതൂ; എഴുതുമ്പോൾ തന്നെ ഫലം മാറും. കുറുക്കുവഴി: 25L = 25 ലക്ഷം, 1.2Cr = 1.2 കോടി, ↑ ↓ കീകൾ കൊണ്ട് സംഖ്യ മാറ്റാം (വലിയ ചുവടിന് Shift).',
    tip2: 'മുൻകൂർ അടവ് ചേർക്കൂ, ഉദാ. വാർഷിക ബോണസിൽ നിന്ന്, എത്ര പലിശ ലാഭിക്കാമെന്ന് കാണൂ. "കാലാവധി കുറയ്ക്കുക" സാധാരണ "EMI കുറയ്ക്കുക"-യേക്കാൾ കൂടുതൽ ലാഭം തരും.',
    tip3: 'ബാങ്ക്, NBFC, കട ജീവനക്കാർ: "ഫ്ലാറ്റ് നിരക്കും യഥാർഥ നിരക്കും", "നോ-കോസ്റ്റ് EMI" എന്നിവ ഉപയോഗിച്ച് ഉപഭോക്താവിന് നിമിഷങ്ങൾക്കുള്ളിൽ യഥാർഥ ചെലവ് കാണിക്കൂ.',
    tip4: 'ഭവന വായ്പ നികുതി രേഖകൾക്ക് സാമ്പത്തിക വർഷ കാഴ്ച ഉപയോഗിക്കൂ; CSV ഡൗൺലോഡ് ചെയ്ത് പട്ടിക Excel-ലോ Google Sheets-ലോ തുറക്കാം.',
    tip5: '"സംഗ്രഹം പകർത്തുക" WhatsApp-നോ ഇമെയിലിനോ ചെറിയ സന്ദേശം തയ്യാറാക്കും, ഇതേ കണക്ക് തുറക്കുന്ന ലിങ്ക് സഹിതം.',
    tip6: 'HR, ഫിനാൻസ് ടീമുകൾ: സാമ്പത്തിക അവബോധ സെഷനിൽ ഇത് പ്രൊജക്ടറിൽ കാണിച്ച് SIP, FD, RD, PPF അടുത്തടുത്ത് താരതമ്യം ചെയ്യൂ.',
    how_title: 'കണക്ക് എങ്ങനെ',
    how_emi: 'EMI = P × r × (1+r)^n ÷ ((1+r)^n − 1); ഇവിടെ P വായ്പ, r വാർഷിക നിരക്ക് ÷ 12 ÷ 100, n മാസങ്ങളുടെ എണ്ണം (0%-ൽ EMI = P ÷ n). ഓരോ മാസവും പലിശ = ബാക്കി വായ്പ × r; EMI-യുടെ ബാക്കി വായ്പ കുറയ്ക്കുന്നു.',
    how_apr: 'കൈയിൽ കിട്ടിയ യഥാർഥ തുക (വായ്പ മൈനസ് ഫീസ്) നിങ്ങളുടെ എല്ലാ EMI-കളുടെയും മൂല്യത്തിന് തുല്യമാകുന്ന വാർഷിക നിരക്കാണ് APR. വായ്പക്കാർ കീ ഫാക്റ്റ് സ്റ്റേറ്റ്മെന്റിൽ (KFS) ഇതേ APR കാണിക്കണം.',
    how_flat: 'ഫ്ലാറ്റ് പലിശ = തുക × ഫ്ലാറ്റ് നിരക്ക് × വർഷം. അതേ EMI തരുന്ന കുറയുന്ന ബാക്കി നിരക്കാണ് യഥാർഥ നിരക്ക്.',
    how_sip: 'SIP: ഓരോ മാസത്തിന്റെയും തുടക്കത്തിൽ നിക്ഷേപിക്കുന്നു, വളർച്ച എല്ലാ മാസവും ചേരുന്നു (വാർഷിക ആദായം ÷ 12), മിക്ക ഫണ്ട് കാൽക്കുലേറ്ററുകളെയും പോലെ. ഒറ്റത്തവണ നിക്ഷേപം വർഷത്തിൽ ഒരിക്കൽ വളരും. നികുതിയും ഫണ്ട് ചാർജുകളും ഉൾപ്പെടുത്തിയിട്ടില്ല.',
    how_fd: 'FD: ഇന്ത്യൻ ബാങ്കുകളെപ്പോലെ ഓരോ പാദത്തിലും കൂട്ടുപലിശ. RD: ഓരോ മാസ നിക്ഷേപവും ഉള്ളിടത്തോളം കാലം ഓരോ പാദത്തിലും വളരും. ബാങ്കുകളുടെ റൗണ്ടിങ്ങിൽ ഏതാനും രൂപയുടെ വ്യത്യാസം വരാം.',
    how_ppf: 'PPF: വർഷം ₹1,50,000 വരെ നിക്ഷേപം, പലിശ വർഷത്തിൽ ഒരിക്കൽ ചേരും, 15 വർഷത്തെ ലോക്ക്-ഇൻ, അത് 5 വർഷം വീതം നീട്ടാം.',
